SELECT 
FROM dms_shop_product


        AND tenant_id = #{tenantId}


        AND status = #{status}


        AND category_name = #{categoryName}


        AND (
            product_name LIKE CONCAT('%', #{keyword}, '%')
            OR subtitle LIKE CONCAT('%', #{keyword}, '%')
            OR product_no LIKE CONCAT('%', #{keyword}, '%')
        )


ORDER BY status DESC, sort_order DESC, id DESC

SELECT DISTINCT category_name FROM dms_shop_product WHERE status = 1
AND tenant_id = #{tenantId}
AND category_name IS NOT NULL AND category_name != '' ORDER BY category_name ASC

mapper.update:
UPDATE dms_shop_product
SET status = #{status}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE dms_shop_product
SET category_name = #{newName}, update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND category_name = #{oldName}
